const truthy = v => ['true', 'yes', 'y', '1'].includes(String(v ?? '').trim().toLowerCase());
const TZ = $env.BUSINESS_TZ_OFFSET || '+05:30';
// Sheets returns "2026-10-10 19:00", ISO strings, or a date serial. Bare times are venue-local (IST).
function parseWhen(v) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v === 'number') {
    const sign = TZ.startsWith('-') ? -1 : 1;
    const [h, m] = TZ.slice(1).split(':').map(Number);
    return new Date((v - 25569) * 864e5 - sign * (h * 60 + (m || 0)) * 6e4);
  }
  let s = String(v).trim().replace(' ', 'T');
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) s += 'T00:00';
  if (!/([zZ]|[+-]\d{2}:?\d{2})$/.test(s)) s += TZ;
  const d = new Date(s);
  return isNaN(d) ? null : d;
}

function segmentOf(c) {
  const visits = Number(c.total_visits) || 0;
  const last = parseWhen(c.last_visit);
  const days = last ? (Date.now() - last) / 864e5 : Infinity;
  if (visits > 0 && days > Number($env.LAPSED_AFTER_DAYS || 45)) return 'lapsed';
  if (visits >= Number($env.VIP_MIN_VISITS || 5)) return 'vip';
  if (visits <= 1) return 'new';
  return 'regular';
}
function birthdayWithin(c, days) {
  const m = String(c.birthday || '').match(/(\d{1,4})[-\/](\d{1,2})(?:[-\/](\d{1,4}))?/);
  if (!m) return false;
  // Accept YYYY-MM-DD, DD-MM-YYYY or DD-MM
  let month, day;
  if (m[1].length === 4) { month = +m[2]; day = +m[3]; } else { day = +m[1]; month = +m[2]; }
  const now = new Date();
  for (let i = 0; i <= days; i++) {
    const d = new Date(now.getTime() + i * 864e5);
    if (d.getMonth() + 1 === month && d.getDate() === day) return true;
  }
  return false;
}
function matchesSegment(c, seg) {
  seg = String(seg || 'all').trim().toLowerCase();
  if (seg === 'all' || seg === '') return true;
  if (seg === 'birthday') return birthdayWithin(c, 7);
  return segmentOf(c) === seg;
}

const lists = JSON.parse($env.BREVO_LISTS || '{}');
const segLists = ['vip', 'regular', 'new', 'lapsed'].filter(s => lists[s]);
const seen = new Set();
const out = [];
for (const { json: c } of $input.all()) {
  const email = String(c.email || '').trim().toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || seen.has(email)) continue;
  seen.add(email);
  if (!truthy(c.email_opt_in)) {
    // Suppress anyone without consent; never re-subscribes a Brevo unsubscribe either way
    out.push({ json: { email, segment: 'suppressed', brevo: { email, emailBlacklisted: true, updateEnabled: true } } });
    continue;
  }
  const seg = segmentOf(c);
  const name = String(c.name || '').trim();
  out.push({ json: { email, segment: seg, brevo: {
    email,
    updateEnabled: true,
    attributes: { FIRSTNAME: name.split(/\s+/)[0] || '', SEGMENT: seg, TOTAL_VISITS: Number(c.total_visits) || 0, LAST_VISIT: c.last_visit || '' },
    listIds: [lists.all, lists[seg]].filter(Boolean).map(Number),
    unlinkListIds: segLists.filter(s => s !== seg).map(s => Number(lists[s])),
  } } });
}
return out;

const results = $input.all();
const failed = results.filter(r => r.json.error).length;
const sent = $('Build Brevo Contacts').all();
const bySeg = {};
for (const { json } of sent) bySeg[json.segment] = (bySeg[json.segment] || 0) + 1;
return [{ json: { count: sent.length - failed, failed, details: JSON.stringify({ bySeg, failed }) } }];

