function parseWhen(v) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v === 'number') {
    const sign = TZ.startsWith('-') ? -1 : 1;
    const [h, m] = TZ.slice(1).split(':').map(Number);
    return new Date((v - 25569) * 864e5 - sign * (h * 60 + (m || 0)) * 6e4);
  }
  let s = String(v).trim().replace(' ', 'T');
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) s += 'T00:00';
  if (!/([zZ]|[+-]\d{2}:?\d{2})$/.test(s)) s += TZ;
  const d = new Date(s);
  return isNaN(d) ? null : d;
}

const now = new Date();
const due = $input.all().map(i => i.json)
  .filter(c => String(c.channel).trim().toLowerCase() === 'email'
    && String(c.status).trim().toLowerCase() === 'approved' && c.campaign_id && c.brief)
  .map(c => ({ ...c, _when: parseWhen(c.send_at) || now }))
  // Build copy up to 24h ahead so Brevo can hold the scheduled send
  .filter(c => c._when - now <= 24 * 3600e3)
  .sort((a, b) => a._when - b._when);
if (!due.length) return [];
const { _when, ...c } = due[0];
return [{ json: { ...c, send_at_iso: _when.toISOString() } }];

const c = $('Pick Due Email Campaign').first().json;
const rows = $input.all().map(i => i.json);
const biz = rows.find(r => c.business_id && r.business_id === c.business_id) || rows[0] || {};
const system = `You are the senior email copywriter for ${biz.business_name || 'a hospitality venue'}, a ${biz.business_type || 'restaurant/club'} in India.
Write one marketing email that gets guests to book. Voice: warm, confident, specific, a little playful. Never generic.
Hard rules:
- Use ONLY facts given below (offers, timings, address, menu). Never invent prices, dates, dishes or discounts.
- Subject <= 50 characters, no ALL CAPS, at most one emoji, no spam words ("FREE!!!", "act now").
- Preview text <= 90 characters, complements the subject.
- Body: 90-160 words. One clear CTA button linking to the booking URL. Mobile-first.
- html_body = inner HTML only (no <html>/<head>/<body>), single 600px column, inline CSS, web-safe fonts, no external CSS, no JavaScript.
- If an image URL is provided, use it once as a full-width hero <img> with descriptive alt text. Otherwise no images.
- Do NOT add an unsubscribe link or address footer — they are appended automatically.
Return ONLY a JSON object: {"subject": "...", "preview_text": "...", "html_body": "..."}`;
const user = JSON.stringify({
  campaign_name: c.name, audience_segment: c.segment || 'all', brief: c.brief, offer: c.offer || '',
  image_url: c.image_url || '', booking_url: $env.BOOKING_URL || '', menu_url: $env.MENU_URL || '',
  venue: { name: biz.business_name, timings: biz.timings, menu_highlights: biz.menu_highlights,
    current_offers: biz.current_offers, vip_options: biz.vip_options, address: biz.address, phone: biz.phone_number },
}, null, 2);
return [{ json: { campaign: c, biz, claude_body: {
  model: $env.CLAUDE_MARKETING_MODEL || 'claude-sonnet-5-5',
  max_tokens: 4000,
  system,
  messages: [{ role: 'user', content: user }],
} } }];

const truthy = v => ['true', 'yes', 'y', '1'].includes(String(v ?? '').trim().toLowerCase());
const TZ = $env.BUSINESS_TZ_OFFSET || '+05:30';
// Sheets returns "2026-10-10 19:00", ISO strings, or a date serial. Bare times are venue-local (IST).
function parseWhen(v) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v === 'number') {
    const sign = TZ.startsWith('-') ? -1 : 1;
    const [h, m] = TZ.slice(1).split(':').map(Number);
    return new Date((v - 25569) * 864e5 - sign * (h * 60 + (m || 0)) * 6e4);
  }
  let s = String(v).trim().replace(' ', 'T');
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) s += 'T00:00';
  if (!/([zZ]|[+-]\d{2}:?\d{2})$/.test(s)) s += TZ;
  const d = new Date(s);
  return isNaN(d) ? null : d;
}

const { campaign: c, biz } = $('Build Email Prompt').item.json;
let copy = null, parse_error = '';
try {
  if ($json.error) throw new Error(JSON.stringify($json.error).slice(0, 200));
  const text = ($json.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
  copy = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
  if (!copy.subject || !copy.html_body) throw new Error('missing subject/html_body');
} catch (e) { parse_error = 'Claude copy failed: ' + e.message; }
if (parse_error) return { json: { campaign: c, parse_error } };

const lists = JSON.parse($env.BREVO_LISTS || '{}');
const seg = String(c.segment || 'all').trim().toLowerCase();
const listId = Number(lists[seg] || lists.all);
const esc = s => String(s || '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const htmlContent = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(copy.subject)}</title></head>
<body style="margin:0;padding:0;background:#f4f4f4;"><div style="max-width:600px;margin:0 auto;background:#ffffff;font-family:Arial,Helvetica,sans-serif;color:#222;">
${copy.html_body}
<div style="padding:24px;font-size:12px;line-height:18px;color:#777;text-align:center;border-top:1px solid #eee;">
${esc(biz.business_name)}${biz.address ? ' · ' + esc(biz.address) : ''}<br>
You're receiving this because you opted in at ${esc(biz.business_name || 'our venue')}. <a href="{{ unsubscribe }}" style="color:#777;">Unsubscribe</a>
</div></div></body></html>`;

const autoSend = truthy(c.auto_send);
const minStart = new Date(Date.now() + 10 * 60e3);
const sendAt = new Date(Math.max(new Date(c.send_at_iso || 0).getTime(), minStart.getTime()));
const body = {
  name: `${c.campaign_id} · ${c.name || seg}`.slice(0, 100),
  subject: copy.subject,
  previewText: copy.preview_text || '',
  sender: { name: $env.BREVO_SENDER_NAME || biz.business_name || 'Team', email: $env.BREVO_SENDER_EMAIL },
  htmlContent,
  recipients: { listIds: [listId] },
};
if (autoSend) body.scheduledAt = sendAt.toISOString();
if (!listId) return { json: { campaign: c, parse_error: `No Brevo list for segment "${seg}" in BREVO_LISTS` } };
return { json: { campaign: c, autoSend, subject: copy.subject, brevo_body: body } };

const a = $('Assemble Brevo Campaign').item.json;
const c = a.campaign;
let status, notes = '', provider_ref = '';
if (a.parse_error) { status = 'failed'; notes = a.parse_error; }
else if ($json.id) {
  provider_ref = String($json.id);
  status = a.autoSend ? 'scheduled' : 'draft_created';
  notes = a.autoSend ? `Scheduled in Brevo for ${a.brevo_body.scheduledAt}` : 'Draft in Brevo — review and send';
} else { status = 'failed'; notes = 'Brevo: ' + JSON.stringify($json.error || $json).slice(0, 300); }
return { json: {
  campaign_id: c.campaign_id, status, provider_ref, subject: a.subject || '', notes,
  alert: status !== 'scheduled',
  alert_text: status === 'draft_created'
    ? `Email draft ready in Brevo: "${a.subject}" (${c.campaign_id}). Review and send.`
    : `Email campaign ${c.campaign_id} ${status}. ${notes}`,
} };
